css:
.loader{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-orbit: calc(var(--loader-size, 56px) / 2.8);
  position:relative;
  display:inline-block;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.loader::before{
  content:"";
  position:absolute;
  top:50%;
  left:50%;
  width:var(--td-dot);
  height:var(--td-dot);
  margin:calc(var(--td-dot) / -2) 0 0 calc(var(--td-dot) / -2);
  border-radius:50%;
  background-color:var(--loader-secondary-color, #a5b4fc);
  animation:td-revolution var(--loader-speed, 1.4s) infinite linear;
}
@keyframes td-revolution{
  from{transform:rotate(0deg) translateX(var(--td-orbit))}
  to{transform:rotate(360deg) translateX(var(--td-orbit))}
}
